using System.Collections.Generic;

namespace PointDeviation
{
    /// <summary>Traduzioni inglesi dei testi dell'interfaccia (chiave = testo italiano come scritto nel codice).</summary>
    internal static partial class L
    {
        static partial void FillEnglish(Dictionary<string, string> d)
        {
            d["Livelli principali pronti: puoi navigare. Il dettaglio fine ({0:F0}% dei punti) si completa in background, circa {1:F0} s."] = "Main levels ready: you can navigate. The fine detail ({0:F0}% of points) is completed in the background, about {1:F0} s.";
            d["Analisi: aspetta il calcolo completo delle distanze"] = "Analysis: wait for all distances to be computed";
            d["Prova: punti disegnati da Revit"] = "Test: points drawn by Revit";
            d["Camera dal faro con i collegamenti"] = "Beacon camera with links";
            d["Solo con il disegno con shader. Acceso (consigliato): nelle immagini che Revit ridisegna in movimento senza chiamare il plugin (con i collegamenti accesi sono molte) la nuvola usa la camera ricavata da pochi punti invisibili consegnati a Revit e segue il modello. Spento: in quelle immagini la nuvola resta indietro di qualche fotogramma. Dopo il cambio ricarica la nuvola in Gestisci › Gestisci collegamenti › Nuvole di punti › Ricarica."] = "Shader drawing only. On (recommended): in the images Revit redraws while moving without calling the plug-in (many with links visible), the cloud uses the camera derived from a few invisible points handed to Revit and follows the model. Off: in those images the cloud lags a few frames behind. After changing it, reload the cloud in Manage › Manage Links › Point Clouds › Reload.";
            d["In movimento: profondità del modello dalla mesh dell'analisi"] = "While moving: model depth from the analysis mesh";
            d["In movimento: profondità del modello dalla mesh"] = "While moving: model depth from the mesh";
            d["Solo con il disegno con shader e la camera dal faro. Acceso (consigliato): nelle immagini che Revit mostra in movimento, la parte del modello che Revit non ha ancora ridisegnato copre la nuvola grazie a una mesh del modello e dei collegamenti visibili, preparata da sola in background per la vista 3D attiva (qualche secondo, Revit resta usabile) e rifatta dopo le modifiche; finché non è pronta si usa quella dell'ultima analisi, se c'è."] = "Shader drawing and beacon camera only. On (recommended): in the images Revit shows while moving, the part of the model Revit has not redrawn yet hides the cloud thanks to a mesh of the model and the visible links, prepared automatically in the background for the active 3D view (a few seconds, Revit stays usable) and rebuilt after changes; until it is ready the mesh of the last analysis is used, if any.";
            d["In pianta e sezione: profondità del fotogramma completo"] = "Plan and section: depth of the complete frame";
            d["Solo con il disegno con shader e la camera dal faro. Acceso (consigliato): in piante, sezioni e prospetti, mentre sposti o zoomi, la nuvola si confronta con la profondità del modello dell'ultimo fotogramma completo, come da fermo, invece che con quella approssimata del faro: non passa più sopra e sotto il modello. Non sposta né la nuvola né il modello: decide solo quale dei due si vede. Spento: comportamento della voce 281."] = "Shader drawing and beacon camera only. On (recommended): in plans, sections and elevations, while panning or zooming, the cloud is compared with the model depth of the last complete frame, as at rest, instead of the approximate beacon depth: it no longer jumps above and below the model. It moves neither the cloud nor the model: it only decides which of the two is shown. Off: behaviour of change 281.";
            d["In pianta e sezione: camera dal faro"] = "Plan and section: beacon camera";
            d["Solo con il disegno con shader. Spento (consigliato): in piante, sezioni e prospetti le immagini che Revit mostra mentre sposti o zoomi usano la camera dell'ultimo fotogramma completo, come prima del faro (la nuvola puo' restare indietro di un attimo ma resta al suo posto). Acceso: anche li' si usa la camera del faro, che in queste viste spesso non coincide con quella del modello."] = "Shader drawing only. Off (recommended): in plans, sections and elevations the images Revit shows while panning or zooming use the camera of the last complete frame, as before the beacon (the cloud may lag for a moment but stays in place). On: the beacon camera is used there too, which in these views often does not match the model camera.";
            d["In pianta e sezione: disegno semplice (come prima)"] = "Plan and section: simple drawing (as before)";
            d["Solo con il disegno con shader. Spento (consigliato): piante, sezioni e prospetti seguono le stesse regole della vista 3D. Acceso, come riserva se nelle viste 2D qualcosa non va: la nuvola si confronta con la profondità che Revit ha in quel fotogramma, senza le correzioni per i fotogrammi parziali (mouse sopra un elemento). In entrambi i casi l'interfaccia resta sopra la nuvola e le correzioni della camera restano."] = "Shader drawing only. Off (recommended): plans, sections and elevations follow the same rules as the 3D view. On, as a fallback if something goes wrong in 2D views: the cloud is compared with the depth Revit has in that frame, without the corrections for partial frames (mouse over an element). Either way the interface stays above the cloud and the camera corrections remain.";
            d["In pianta e sezione: nuvola sotto i riempimenti del modello"] = "Plan and section: cloud under model fills";
            d["Solo con il disegno con shader. Acceso (consigliato): in piante, sezioni e prospetti Revit decide cosa sta sopra con l'ordine dei disegni, non con la profondità. Nelle immagini che Revit mostra mentre sposti, zoomi o passi col mouse la nuvola si disegna nello stesso punto dei fotogrammi completi (prima dei riempimenti del modello), invece che sopra tutto. Spento: in quelle immagini la nuvola può coprire il modello."] = "Shader drawing only. On (recommended): in plans, sections and elevations Revit decides what is on top by drawing order, not by depth. In the images Revit shows while panning, zooming or hovering, the cloud is drawn at the same point as in complete frames (before the model fills) instead of over everything. Off: in those images the cloud may cover the model.";
            d["Mesh anche senza collegamenti"] = "Mesh also without links";
            d["Solo con la profondità dalla mesh. Spento (consigliato): la mesh del modello si prepara solo nelle viste 3D con collegamenti visibili, dove serve (senza collegamenti la profondità di Revit basta) e Revit resta più leggero. Acceso: la mesh si prepara in tutte le viste 3D."] = "Model depth from the mesh only. Off (recommended): the model mesh is prepared only in 3D views with visible links, where it is needed (without links Revit's depth is enough), and Revit stays lighter. On: the mesh is prepared in every 3D view.";
            d["In pianta e sezione: profondità come l'RCP"] = "Plan and section: depth like an RCP";
            d["Solo con «nuvola nello stesso punto dell'RCP». Acceso (consigliato): al posto del faro la nuvola usa le stesse regole di profondità che Revit usa per le sue nuvole, così si vede come un RCP invece di sparire dietro il modello in un'immagine sì e una no. Non sposta né la nuvola né il modello: decide solo quale dei due si vede. Spento: regole di profondità del plugin (voce 297)."] = "Only with «cloud at the same point as an RCP». On (recommended): at the beacon the cloud uses the same depth rules Revit uses for its own clouds, so it looks like an RCP instead of vanishing behind the model every other image. It moves neither the cloud nor the model: it only decides which of the two is shown. Off: the plug-in's own depth rules (change 297).";
            d["In pianta e sezione: niente ridisegno sopra l'interfaccia al passaggio del mouse"] = "Plan and section: no redraw over the interface when hovering";
            d["Solo con «nuvola nello stesso punto dell'RCP». Acceso (consigliato): quando passi col mouse Revit non ridisegna il modello e riusa l'immagine di prima, che contiene già la nuvola; il plugin non la ridisegna sopra, così non salta sopra e sotto i riempimenti del modello a ogni movimento. Non sposta né la nuvola né il modello. Spento: come la 298 (nuvola ridisegnata in ogni immagine)."] = "Only with «cloud at the same point as an RCP». On (recommended): when you hover, Revit does not redraw the model and reuses the previous image, which already contains the cloud; the plug-in does not draw it again on top, so it no longer jumps above and below the model fills at every move. It moves neither the cloud nor the model. Off: as in change 298 (cloud redrawn in every image).";
            d["In pianta e sezione: nuvola nello stesso punto dell'RCP"] = "Plan and section: cloud at the same point as an RCP";
            d["Solo con il disegno con shader. Acceso (consigliato): in piante, sezioni e prospetti Revit decide cosa sta sopra con l'ordine dei disegni; la nuvola si disegna nel punto in cui Revit disegna le sue nuvole (come un RCP), in tutte le immagini, con la camera dell'ultimo fotogramma completo: niente più nuvola che salta sopra e sotto il modello. Mentre sposti la vista può restare indietro di un attimo. Spento: come prima (voce 294)."] = "Shader drawing only. On (recommended): in plans, sections and elevations Revit decides what is on top by drawing order; the cloud is drawn where Revit draws its own clouds (like an RCP), in every image, with the camera of the last complete frame: no more cloud jumping above and below the model. While panning it may lag for a moment. Off: as before (change 294).";
            d["In movimento: stessa tolleranza di Revit sulle superfici del modello"] = "While moving: same tolerance as Revit on model surfaces";
            d["Solo con la profondità dalla mesh. Acceso (consigliato): in movimento la mesh usa lo stesso scarto di profondità che Revit usa da fermo per il suo modello (misurato nei fotogrammi completi; finché non c'è, 1 cm), così i punti sulle superfici modellate si vedono come da fermo. Non sposta né la nuvola né il modello: decide solo quale dei due si vede. Spento: in movimento le facciate possono comparire a chiazze."] = "Model depth from the mesh only. On (recommended): while moving, the mesh uses the same depth offset Revit uses at rest for its model (measured in complete frames; 1 cm until then), so points on modelled surfaces look as they do at rest. It moves neither the cloud nor the model: it only decides which of the two is shown. Off: while moving, facades may look patchy.";
            d["Solo con il disegno con shader e la camera dal faro. Acceso (consigliato): nelle immagini che Revit mostra in movimento, la parte del modello che Revit non ha ancora ridisegnato copre la nuvola grazie alla mesh dell'ultima analisi (modello e collegamenti). Senza analisi non cambia niente."] = "Shader drawing and beacon camera only. On (recommended): in the images Revit shows while moving, the part of the model Revit has not redrawn yet hides the cloud thanks to the mesh of the last analysis (model and links). Without an analysis nothing changes.";
            d["Solo con il disegno con shader. Spento (consigliato): come sempre. Acceso: con i collegamenti accesi, nelle immagini che Revit ridisegna in movimento senza chiamare il plugin la nuvola usa la camera ricavata da pochi punti invisibili consegnati a Revit. Dopo il cambio ricarica la nuvola in Gestisci › Gestisci collegamenti › Nuvole di punti › Ricarica."] = "Shader drawing only. Off (recommended): as usual. On: with links visible, in the images Revit redraws while moving without calling the plug-in, the cloud uses the camera derived from a few invisible points handed to Revit. After changing it, reload the cloud in Manage › Manage Links › Point Clouds › Reload.";
            d["Spento (consigliato): i punti li disegna il plugin. Acceso: li disegna Revit come le sue nuvole (punti tondi, grandezza che segue lo zoom senza ricostruzioni), senza colori per deviazione, fuoco e «Dimensione punti». Dopo il cambio ricarica la nuvola in Gestisci › Gestisci collegamenti › Nuvole di punti › Ricarica."] = "Off (recommended): the plug-in draws the points. On: Revit draws them like its own clouds (round points, size that follows the zoom without rebuilding), without deviation colors, focus and «Point size». After changing it, reload the cloud in Manage › Manage Links › Point Clouds › Reload.";
            d["PointDeviation {0}, modifica {1}, compilato il {2}."] = "PointDeviation {0}, change {1}, built on {2}.";
            d["Prova DirectX (sperimentale)"] = "DirectX test (experimental)";
            d["Carica la libreria PdRender.dll e scrive nel registro, ogni 5 secondi, se il disegno di Revit passa da un contesto DirectX 11 che possiamo usare. Non cambia la visualizzazione. Serve Revit riavviato dopo l'attivazione."] = "Loads the PdRender.dll library and writes to the log, every 5 seconds, whether Revit drawing goes through a DirectX 11 context we can use. It does not change the display. Restart Revit after enabling it.";
            d["Disegno con shader (sperimentale)"] = "Shader drawing (experimental)";
            d["Acceso: la nuvola la disegna la libreria PdRender.dll direttamente nella scheda video, con punti tondi la cui grandezza segue lo zoom senza ricostruire nulla. Serve PdRender.dll accanto al plugin e Revit riavviato. Finché la libreria non è pronta si usa il disegno di sempre. Salva il progetto prima di provarlo."] = "On: the cloud is drawn by the PdRender.dll library directly on the graphics card, with round points whose size follows the zoom without rebuilding anything. Requires PdRender.dll next to the plug-in and Revit restarted. Until the library is ready the usual drawing is used. Save the project before trying it.";
            d["Limite di punti fisso"] = "Fixed point limit";
            d["Spento (consigliato): il limite si adatta alla velocità di disegno misurata, scendendo quando la scheda video è lenta (altri programmi aperti, batteria) e risalendo quando c'è margine. Acceso: vale sempre il limite del profilo."] = "Off (recommended): the limit adapts to the measured drawing speed, going down when the graphics card is slow (other programs open, battery) and up again when there is headroom. On: the profile limit always applies.";
            d["Navigazione: stesso dettaglio su tutta la vista"] = "Navigation: same detail across the whole view";
            d["Riconverti dal file originale…"] = "Convert again from the original file…";
            d["File originale di «{0}»"] = "Original file of “{0}”";
            d["Riconvertire «{0}» da\n{1}?\n\nLa nuvola resta inserita nei progetti con la stessa posizione; intanto si continua a usare la versione attuale, che alla fine viene sostituita. Le distanze dell'analisi si ricalcolano."] = "Convert “{0}” again from\n{1}?\n\nThe cloud stays in the projects with the same placement; the current version is used meanwhile and replaced at the end. Analysis distances are computed again.";
            d["Sostituzione della versione precedente non riuscita: "] = "Replacing the previous version failed: ";
            d["Spento (consigliato): dettaglio pieno al centro della finestra, sempre più rado verso i bordi; si leggono e si preparano molti meno punti. Acceso: tutta la vista con lo stesso dettaglio."] = "Off (recommended): full detail at the centre of the window, sparser towards the edges; far fewer points are read and prepared. On: the same detail across the whole view.";
            d["Navigazione: mostra la vista nuova solo quando è pronta"] = "Navigation: show the new view only when it is ready";
            d["Spento (consigliato): zoomando e spostandosi il dettaglio compare man mano, zona per zona. Acceso: resta la vista precedente, ingrandita come un'immagine, e si passa a quella nuova tutta insieme quando è pronta (al massimo dopo 1,2 s)."] = "Off (recommended): while zooming and moving, detail appears progressively, area by area. On: the previous view stays, enlarged like an image, and the new view replaces it all at once when ready (after 1.2 s at most).";
            d["Spento (consigliato): la finestra si chiude quando sono pronti i livelli principali (circa un terzo del tempo) e il dettaglio fine si completa in background. Acceso: si aspetta tutto, poi ogni zoom è pronto e la percentuale di punti vicini al modello è esatta."] = "Off (recommended): the window closes when the main levels are ready (about a third of the time) and the fine detail is completed in the background. On: wait for everything, then every zoom level is ready and the share of points near the model is exact.";
            d["Automatico (questo computer: {0})"] = "Automatic (this computer: {0})";
            d["Leggero"] = "Light";
            d["Medio"] = "Medium";
            d["Potente"] = "Powerful";
            d["Personalizzato"] = "Custom";
            d["Profilo"] = "Profile";
